}
function PSS:L(key)
  local lang = (PetSkillScoutDB and PetSkillScoutDB.language) or "en"
  local dict = self.Locale[lang] or self.Locale.en
  return dict[key] or self.Locale.en[key] or key
end
function PSS:NameAbility(key)
  -- Keep ability names in English in every language.
  local dict = self.Locale.en
  return (dict.abilitiesNames and dict.abilitiesNames[key]) or key
end
function PSS:NameFamily(key)
  local lang = (PetSkillScoutDB and PetSkillScoutDB.language) or "en"
  local dict = self.Locale[lang] or self.Locale.en
  return (dict.familyNames and dict.familyNames[key]) or key
end
function PSS:LanguageName(code)
  for _, item in ipairs(self.languageOptions) do if item.code == code then return item.name end end
  return "English"
end

